mapper.select:
SELECT kv.id, kv.document_id AS documentId, kv.chunk_index AS chunkIndex, kv.content, jsonb_build_object('documentTitle', kd.title, 'source', CASE WHEN kv.user_id > 0 AND kd.type = 1 AND kd.file_status = 1 THEN '/knowledge-document/' || kd.id || '/download' ELSE NULL END) AS metadata, kd.metadata->>'docCategory' AS docCategory, (1 - (kv.embedding <=> CAST(#{queryEmbedding} AS vector))) AS score FROM knowledge_vectors kv JOIN knowledge_documents kd ON kd.id = kv.document_id JOIN knowledge_bases kb ON kb.id = kv.knowledge_id WHERE kd.user_id = kv.user_id AND kd.knowledge_id = kv.knowledge_id AND kb.user_id = kv.user_id AND ((kv.user_id > 0 AND kb.scope = 1) OR (kv.user_id = 0 AND kb.scope IN (2, 3))) AND kd.file_status = 1 AND kd.embedding_status = 3 AND kv.user_id = #{userId} AND kv.knowledge_id = #{knowledgeId} AND kv.document_id IN
#{did}
ORDER BY kv.embedding <=> CAST(#{queryEmbedding} AS vector) LIMIT #{limit}
